public void applyCors(HttpServletRequest req, HttpServletResponse resp) {
    // Получаем заголовок Origin из входящего запроса.
    // Этот заголовок отправляет браузер, указывая источник (домен) запроса.
    String origin = req.getHeader("Origin");

    // Если заголовок Origin отсутствует, значит запрос не является кросс-доменным
    // (или отправлен не из браузера), поэтому нет необходимости применять CORS-заголовки.
    if (origin == null) {
        return;
    }

    // Проверяем, разрешён ли данный источник (origin).
    // Разрешение выдаётся, если:
    // 1. Origin явно находится в списке разрешённых доменов (allowedOrigins), ИЛИ
    // 2. Включена поддержка поддоменов (allowSubdomains) и origin является поддоменом базового домена (baseDomain).
    boolean allowed = allowedOrigins.contains(origin)
        || (allowSubdomains && origin.endsWith("." + baseDomain));

    // Если источник не разрешён, возвращаем ошибку 403 Forbidden и прекращаем обработку.
    // Это предотвращает доступ с неавторизованных доменов.
    if (!allowed) {
        resp.setStatus(HttpServletResponse.SC_FORBIDDEN);
        return;
    }

    // Устанавливаем заголовок Access-Control-Allow-Origin, равный значению Origin из запроса.
    // Это разрешает браузеру принимать ответ от данного источника.
    resp.setHeader("Access-Control-Allow-Origin", origin);

    // Разрешаем отправку учётных данных (cookies, заголовки авторизации) в кросс-доменных запросах.
    // Важно: при использовании этого заголовка значение Access-Control-Allow-Origin не может быть "*".
    resp.setHeader("Access-Control-Allow-Credentials", "true");

    // Добавляем заголовок Vary: Origin, чтобы кэширующие серверы и браузеры корректно
    // обрабатывали ответы для разных источников (Origin).
    resp.addHeader("Vary", "Origin");

    // Если метод запроса — OPTIONS (предварительный запрос, preflight request),
    // то необходимо вернуть информацию о разрешённых методах и времени кэширования этого решения.
    if ("OPTIONS".equalsIgnoreCase(req.getMethod())) {
        // Указываем список HTTP-методов, разрешённых для кросс-доменных запросов.
        resp.setHeader("Access-Control-Allow-Methods", "GET, POST, PUT, DELETE");

        // Указываем время (в секундах), в течение которого браузер может кэшировать
        // результат предварительного запроса, чтобы не отправлять его повторно.
        resp.setHeader("Access-Control-Max-Age", "600");

        // Возвращаем статус 204 No Content, так как предварительный запрос не должен содержать тело ответа.
        resp.setStatus(HttpServletResponse.SC_NO_CONTENT);
    }
}
