func run(srv *http.Server, timeout time.Duration) error {
	// Создаём буферизованный канал для получения ошибок из горутини с сервером.
	// Буфер размером 1 нужен, чтобы горутина не блокировалась при отправке ошибки,
	// даже если основной поток уже завершил работу (например, получил сигнал остановки).
	errCh := make(chan error, 1)

	// Запускаем HTTP-сервер в отдельной горутине, чтобы не блокировать основной поток.
	go func() {
		// Запускаем сервер. ListenAndServe блокирует выполнение до тех пор,
		// пока сервер не будет остановлен или не возникнет ошибка.
		if err := srv.ListenAndServe(); err != nil && !errors.Is(err, http.ErrServerClosed) {
			// Если ошибка не связана с штатным закрытием сервера (ErrServerClosed),
			// отправляем её в канал для обработки в основном потоке.
			errCh <- err
		}
	}()

	// Создаём канал для приёма сигналов операционной системы.
	// Буфер размером 1 гарантирует, что сигнал не будет потерян,
	// если основной поток ещё не готов его принять.
	stop := make(chan os.Signal, 1)

	// Регистрируем обработчик сигналов SIGINT (Ctrl+C) и SIGTERM (завершение процесса).
	// При получении этих сигналов они будут отправлены в канал stop.
	signal.Notify(stop, syscall.SIGINT, syscall.SIGTERM)

	// Ожидаем либо ошибку от сервера, либо сигнал остановки.
	select {
	case err := <-errCh:
		// Если сервер завершился с ошибкой (не штатно), возвращаем эту ошибку.
		return err
	case <-stop:
		// Если получен сигнал остановки (SIGINT или SIGTERM),
		// продолжаем выполнение для корректного завершения работы сервера.
	}

	// Создаём контекст с таймаутом для graceful shutdown.
	// Это гарантирует, что процесс завершения не зависнет навсегда,
	// если какие-то соединения не закроются в разумное время.
	ctx, cancel := context.WithTimeout(context.Background(), timeout)
	defer cancel()

	// Инициируем корректное завершение работы сервера.
	// Shutdown останавливает приём новых соединений, но позволяет
	// завершить обработку уже существующих запросов в пределах таймаута.
	return srv.Shutdown(ctx)
}
