/// Разбирает строку с именем Docker-образа и возвращает кортеж из:
/// (реестр, репозиторий, тег, дайджест).
/// Возвращает None, если формат строки некорректен.
pub fn parse_image(s: &str) -> Option<(&str, &str, Option<&str>, Option<&str>)> {
    // Пытаемся отделить дайджест (например, "sha256:...") от остальной части строки.
    // Если символ '@' найден, проверяем, что после него идёт корректный префикс "sha256:".
    // Если '@' есть, но дайджест некорректный — возвращаем None.
    // Если '@' нет, то дайджест отсутствует, и вся строка остаётся в `rest`.
    let (rest, digest) = match s.split_once('@') {
        Some((r, d)) if d.starts_with("sha256:") => (r, Some(d)),
        Some(_) => return None,
        None => (s, None),
    };

    // Пытаемся отделить тег от имени образа, ища последнее двоеточие.
    // Тег считается корректным, если после двоеточия нет слэша (иначе это часть пути, а не тег).
    // Если двоеточие не найдено или тег содержит слэш, тег считается отсутствующим.
    let (name, tag) = match rest.rsplit_once(':') {
        Some((n, t)) if !t.contains('/') => (n, Some(t)),
        _ => (rest, None),
    };

    // Пытаемся отделить реестр от репозитория, ища первый слэш.
    // Реестр считается корректным, если он содержит точку, двоеточие (порт) или равен "localhost".
    // Если слэш не найден или первая часть не похожа на реестр, используется реестр по умолчанию "docker.io",
    // а вся строка `name` становится репозиторием.
    let (registry, repository) = match name.split_once('/') {
        Some((r, p)) if r.contains('.') || r.contains(':') || r == "localhost" => (r, p),
        _ => ("docker.io", name),
    };

    // Проверяем, что репозиторий не пустой и тег (если есть) не пустой.
    // Если какое-то из условий нарушено, возвращаем None.
    if repository.is_empty() || tag == Some("") {
        return None;
    }

    // Возвращаем успешно разобранные компоненты образа.
    Some((registry, repository, tag, digest))
}
```

