  // Здесь можно реализовать логику, но для простого теста достаточно
  // вернуть объект, который "всегда не совпадает" или "всегда совпадает"
  // в зависимости от того, что ожидает хук.
  // Для теста "маленький экран" обычно достаточно, чтобы matchMedia
  // возвращал matches: true для мобильных запросов.
  return {
    matches: false, // по умолчанию — не совпадает
    media: query,
    onchange: null,
    addListener: jest.fn(), // устаревший API, но некоторые библиотеки его используют
    removeListener: jest.fn(),
    addEventListener: jest.fn(),
    removeEventListener: jest.fn(),
    dispatchEvent: jest.fn(),
  };
};

it('shows the menu button on small screens', () => {
  // Подменяем window.matchMedia на мок
  Object.defineProperty(window, 'matchMedia', {
    writable: true,
    value: jest.fn().mockImplementation(mockMatchMedia),
  });

